\documentclass{article}
\usepackage{fontspec}
\setmainfont{Noto Sans Bengali}
\begin{document}

আবাসস্থল ও বিস্তার: ব্রায়োফাইটা বিভাগের উদ্ভিদসমূহকে প্রাথমিক স্থালজ উদ্ভিদ হিসেবে বিবেচনা করা হয়। ছায়াময় ভেজা আর্দ্র মাটি, পুরাতন প্রাচীর, নুড়ি পাথর ও প্রাচীন গাছের বাকলের উপর ব্রায়োফাইট জন্মাতে দেখা যায়। এদের বেশ কিছু প্রজাতি পানিতে জন্মে। পৃথিবীর প্রায় সকল মরু অঞ্চলে ব্রায়োফাইট জাতীয় উদ্ভিদ জন্মে। দাজিলিং-কে ব্রায়োফাইটের স্বর্গ বলা হয়।

\subsection{ব্রায়োফাইটের বৈশিষ্ট্য (Characteristics of Bryophyte)}

\begin{enumerate}
    \item এরা বহুকায়ি অপুষ্পক উদ্ভিদ অর্থাৎ এদের কোনো ফুল, ফল ও বীজ হয় না।
    \item দেহ থ্যালয়েড প্রকৃতির অর্থাৎ এদের দেহকে মূল, কাঁচ ও পাতায় বিভক্ত করা যায় না।
    \item মূলের পরিবর্তে রাইজয়েড থাকে। রাইজয়েড এককোষী বা বহুকোষী।
    \item দেহ শুধুমাত্র প্যারেনকাইমা টিস্যু দিয়ে গঠিত।
    \item পরিবহন টিস্যু অনুপস্থিত।
    \item জননাজা বহুকোষী, বন্ধ্যাকোষের আবরণ যুক্ত; পুং জননাজকে অ্যান্থেরিডিয়াম এবং স্ত্রী জননাজকে অর্কিগোনিয়াম বলে।
    \item যৌন জনন উপযোগী প্রকৃতির অর্থাৎ বড় নিশ্চল স্ত্রী গ্যামিটের (ডিম্বাণু) সাথে ক্ষুদ্র ও সচল পুংগ্যামিটের (শুক্রাণু) মিলন ঘটে।
    \item শুক্রাণু দ্বিফ্যাজেলে বিশিষ্ট।
    \item নিমেকের জন্য জলীয় মাধ্যমের প্রয়োজন হয়।
    \item বহুকোষী ভূগুল উৎপন্ন হয় এবং ভূগুল স্ত্রী জননাজকের অভ্যন্তরে থাকে।
    \item স্পোরোফাইটিক উদ্ভিদ শুধুমাত্র ক্যাপসুল বা ফুট, সিটা ও ক্যাপসুল বিভক্ত।
    \item স্পোরোফাইটিক উদ্ভিদ পৃষ্ঠ ও আশ্রয়ের জন্য গ্যামিটোফাইটিক উদ্ভিদের উপর নির্ভরশীল। স্পোরোফাইট হোমোস্পোরাস অর্থাৎ স্পোরোফাইট একই ধরনের স্পোর তৈরি করে থাকে।
    \item ব্রায়োফাইভাবৃত্ত উদ্ভিদগুলোর জীবনচক্রে সুস্পষ্ট পৃথক দুটি জনু (গ্যামিটোফাইটিক ও স্পোরোফাইটিক) পরিলক্ষিত হয়।
    \item স্পোর অজুরিত হয়ে সরাসরি থ্যালাস গঠন করে বা প্রোটোনোমা উৎপন্ন করে।
    \item প্রধান উদ্ভিদ দেহটি গ্যামিটোফাইট অর্থাৎ হ্যাপ্লয়েড (n)। গ্যামিটোফাইট সবুজ, স্বতন্ত্র ও স্বভাজী।
\end{enumerate}

\end{document}

